'use strict';
// Runs the Android app's fallback players (generated by its unit tests into
// android/build/player-pages) in real Chromium — Android's WebView is Chromium too.
// Run: (cd android && ./gradlew testDebugUnitTest) && node test/player-pages.js

const assert = require('assert/strict');
const fs = require('fs');
const path = require('path');
const http = require('http');
const { chromium } = require('playwright');
const { startFixtures } = require('./fixtures');

const PAGES = path.join(__dirname, '..', 'android', 'app', 'build', 'player-pages');
const HLS_JS = path.join(__dirname, '..', 'android', 'app', 'src', 'main', 'assets', 'hls.min.js');

(async () => {
  assert.ok(fs.existsSync(PAGES), 'run the Android unit tests first');
  const fixtures = await startFixtures();
  const F = `http://127.0.0.1:${fixtures.address().port}`;
  // Same origin for player pages and media, like the app's "page address" trick.
  const server = http.createServer((req, res) => {
    const p = new URL(req.url, 'http://x').pathname;
    if (p === '/__meh__/hls.min.js') { res.writeHead(200, { 'Content-Type': 'application/javascript' }); return fs.createReadStream(HLS_JS).pipe(res); }
    if (p.startsWith('/player/')) { res.writeHead(200, { 'Content-Type': 'text/html' }); return res.end(fs.readFileSync(path.join(PAGES, p.slice(8)))); }
    http.get(F + req.url, (up) => { res.writeHead(up.statusCode, up.headers); up.pipe(res); }).on('error', () => res.writeHead(502).end());
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const B = `http://127.0.0.1:${server.address().port}`;
  const browser = await chromium.launch({ args: ['--autoplay-policy=no-user-gesture-required'] });
  let passed = 0;

  async function open(url, after) {
    const page = await browser.newPage();
    // Stand-in for the app's JavaScript bridge: records what the player reports.
    await page.addInitScript(() => {
      window.__events = [];
      window.Meh = {
        started: (t) => __events.push(['started', t]), ended: (t) => __events.push(['ended', t]),
        failed: (t, why) => __events.push(['failed', t, why]), muted: (t) => __events.push(['muted', t]),
        duration: (t, s) => __events.push(['duration', t, s]),
      };
    });
    await page.goto(url);
    if (after) await after(page);
    return page;
  }
  const waitEvent = (page, name, ms = 15000) => page.waitForFunction((n) => __events.some((e) => e[0] === n), name, { timeout: ms });
  const step = async (name, fn) => { process.stdout.write(`• ${name} … `); await fn(); passed++; console.log('ok'); };

  await step('Chrome player: plays a file, reports start and end', async () => {
    const page = await open(`${B}/player/web-file.html`);
    await waitEvent(page, 'started');
    await page.evaluate(() => { const v = document.querySelector('video'); v.currentTime = v.duration - 0.3; });
    await waitEvent(page, 'ended');
    const ev = await page.evaluate(() => __events);
    assert.deepEqual(ev.find((e) => e[0] === 'started'), ['started', 11]);
    const d = ev.find((e) => e[0] === 'duration');
    assert.ok(d && Math.round(d[2]) === 60, `reports the video's length for the minimum-length slider (${d && d[2]})`);
    await page.close();
  });

  await step('Chrome player: HLS stream (native HLS where Chrome has it)', async () => {
    const page = await open(`${B}/player/web-hls.html`);
    await waitEvent(page, 'started', 20000);
    await page.close();
  });

  await step('Chrome player: HLS through the bundled hls.js where Chrome lacks native HLS', async () => {
    const page = await browser.newPage();
    await page.addInitScript(() => {
      window.__events = [];
      window.Meh = { started: (t) => __events.push(['started', t]), ended: () => {}, failed: (t, w) => __events.push(['failed', t, w]), muted: () => {}, duration: () => {} };
      // Pretend this Chrome has no native HLS (like some phones' WebViews).
      const orig = HTMLMediaElement.prototype.canPlayType;
      HTMLMediaElement.prototype.canPlayType = function (t) { return /mpegurl/i.test(t) ? '' : orig.call(this, t); };
    });
    await page.goto(`${B}/player/web-hls.html`);
    await waitEvent(page, 'started', 20000);
    assert.ok(await page.evaluate(() => !!window.Hls), 'bundled hls.js was served and used');
    await page.close();
  });

  await step('Chrome player: a broken link reports failure (so the app moves on)', async () => {
    const page = await open(`${B}/player/web-broken.html`);
    await waitEvent(page, 'failed');
    await page.close();
  });

  await step("site-page mode: starts the page's video and fills the screen", async () => {
    const script = fs.readFileSync(path.join(PAGES, 'page-script.js'), 'utf8');
    const page = await open(`${B}/static-video.html`, (p) => p.evaluate(script));
    await waitEvent(page, 'started');
    const style = await page.evaluate(() => getComputedStyle(document.querySelector('video')).position);
    assert.equal(style, 'fixed', 'video enlarged to fill the screen');
    await waitEvent(page, 'duration');
    await page.evaluate(() => { const v = document.querySelector('video'); v.currentTime = v.duration - 0.3; });
    await waitEvent(page, 'ended');
    await page.close();
  });

  console.log(`\n${passed} player checks passed`);
  await browser.close(); server.close(); fixtures.close();
  process.exit(0);
})().catch((e) => { console.log('FAILED'); console.error(e); process.exit(1); });
